namespace docking.widgets.pathmanager;

using docking;

public abstract class AbstractPathsDialog : DialogComponentProvider {

	protected PathnameTablePanel tablePanel;

	protected AbstractPathsDialog(string title) : base(title)
    {
		tablePanel = newPathnameTablePanel();
		tablePanel.getAccessibleContext().setAccessibleName("Edit Paths");
		addWorkPanel(tablePanel);
		addOKButton();
		addCancelButton();
		setPreferredSize(600, 400);
		setRememberSize(false);
	}

	protected abstract string[] loadPaths();

	protected abstract void savePaths(string[] paths);

	protected abstract PathnameTablePanel newPathnameTablePanel();

	protected void reset() {
		string[] paths = loadPaths();
		tablePanel.setPaths(paths);
	}

	/* @Override */
	protected void okCallback() {
		string[] paths = tablePanel.getPaths();
		savePaths(paths);
		close();
	}
}
